styl:
@media screen and (max-width: 600px){.iqbr-section-header--text-pad-small{padding-left:20px !important;padding-right:20px !important}}
.iqbr-section-header--pb0{padding-bottom:0 !important}
.iqbr-section-header--pt0{padding-top:0}
.iqbr-logo--center{text-align:center;margin:0 auto}
.iqbr-logo--logo{float:none;max-width:146px;padding-top:32px;padding-bottom:28px}
@media screen and (max-width: 600px){.iqbr-logo--logo{margin:0 auto !important}}
.iqbr-section-dark--brad-full{border-radius:32px !important}
